            } catch (NumberFormatException e) {
                continue;
            }
            if (isInTimeRange(ts, timeRanges)) {
                // create snapshot; assume constructor takes line without timestamp part
                String snapshotData = line.substring(comma + 1);
                result.add(new ThreadSnapshot(ts, snapshotData));
            }
        }
    }
    return result;
}

